210	func loadLocalReviewManifests(ctx context.Context, worktreeRoot string) ([]LocalReviewManifest, error) {
211		dir, err := localReviewManifestDir(ctx)
212		if err != nil {
213			return nil, err
214		}
215		entries, err := os.ReadDir(dir)
216		if errors.Is(err, os.ErrNotExist) {
217			return nil, nil
218		}
219		if err != nil {
220			return nil, fmt.Errorf("read review manifest dir: %w", err)
221		}
222	
223		manifests := make([]LocalReviewManifest, 0, len(entries))
224		for _, entry := range entries {
225			if entry.IsDir() || filepath.Ext(entry.Name()) != ".json" {
226				continue
227			}
228			b, readErr := os.ReadFile(filepath.Join(dir, entry.Name())) //nolint:gosec // entry names come directly from os.ReadDir(dir).
229			if readErr != nil {
230				return nil, fmt.Errorf("read review manifest %s: %w", entry.Name(), readErr)
231			}
232			var manifest LocalReviewManifest
233			if err := json.Unmarshal(b, &manifest); err != nil {
234				return nil, fmt.Errorf("decode review manifest %s: %w", entry.Name(), err)
235			}
236			if worktreeRoot != "" && manifest.WorktreePath != "" && manifest.WorktreePath != worktreeRoot {
237				continue
238			}
239			manifests = append(manifests, manifest)
240		}
241		sort.SliceStable(manifests, func(i, j int) bool {
242			return manifests[i].CreatedAt.After(manifests[j].CreatedAt)
243		})
244		return manifests, nil
245	}
