247	func localReviewManifestDir(ctx context.Context) (string, error) {
248		worktreeRoot, err := paths.WorktreeRoot(ctx)
249		if err != nil {
250			return "", fmt.Errorf("resolve worktree root: %w", err)
251		}
252		commonDir, err := runGit(ctx, worktreeRoot, "rev-parse", "--git-common-dir")
253		if err != nil {
254			return "", fmt.Errorf("resolve git common dir: %w", err)
255		}
256		commonDir = strings.TrimSpace(commonDir)
257		if commonDir == "" {
258			return "", errors.New("git common dir is empty")
259		}
260		if !filepath.IsAbs(commonDir) {
261			commonDir = filepath.Join(worktreeRoot, commonDir)
262		}
263		return filepath.Join(commonDir, "entire-review", "manifests"), nil
264	}
