266	func localReviewManifestFilename(manifest LocalReviewManifest) string {
267		name := manifest.CreatedAt.UTC().Format("20060102T150405")
268		if len(manifest.Sources) > 0 && manifest.Sources[0].SessionID != "" {
269			name += "-" + safeManifestFilenamePart(manifest.Sources[0].SessionID)
270		}
271		return name + ".json"
272	}
