274	func safeManifestFilenamePart(value string) string {
275		value = strings.TrimSpace(value)
276		if value == "" {
277			return "review"
278		}
279		var b strings.Builder
280		for _, r := range value {
281			if r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' || r == '-' || r == '_' || r == '.' {
282				b.WriteRune(r)
283				continue
284			}
285			b.WriteByte('-')
286		}
287		return b.String()

