93	func matchReviewSessionState(
94		worktreeRoot string,
95		headSHA string,
96		runStartedAt time.Time,
97		agentName string,
98		states []*session.State,
99		used map[string]bool,
100	) *session.State {
101		wantAgentType := agentTypeForReviewAgent(agentName)
102		var best *session.State
103		for _, st := range states {
104			if st == nil || used[st.SessionID] || st.Kind != session.KindAgentReview {
105				continue
106			}
107			if worktreeRoot != "" && st.WorktreePath != "" && st.WorktreePath != worktreeRoot {
108				continue
109			}
110			if headSHA != "" && st.BaseCommit != "" && st.BaseCommit != headSHA {
111				continue
112			}
113			if !runStartedAt.IsZero() && st.StartedAt.Before(runStartedAt.Add(-5*time.Second)) {
114				continue
115			}
116			if wantAgentType != "" && st.AgentType != "" && st.AgentType != wantAgentType {
117				continue
118			}
119			if best == nil || st.StartedAt.After(best.StartedAt) {
120				best = st
121			}
122		}
123		return best
124	}
