105	// isWarnableStaleEndedSession reports whether an ENDED session is still both
106	// expensive in PostCommit and actionable via 'entire doctor'.
107	func isWarnableStaleEndedSession(repo *git.Repository, state *SessionState) bool {
108		if state.Phase != session.PhaseEnded || state.FullyCondensed || state.StepCount <= 0 {
109			return false
110		}
111	
112		// Re-check shadow branch existence even though listAllSessionStates already
113		// filters orphaned sessions. This is intentional: PostCommit deletes shadow
114		// branches during condensation, so a branch that existed at list-load time
115		// may be gone by the time we reach the warning check. Without this re-check
116		// we would warn about sessions that this commit just cleaned up.
117		shadowBranch := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
118		refName := plumbing.NewBranchReferenceName(shadowBranch)
119		_, err := repo.Reference(refName, true)
120		return err == nil
121	}
