441	func (s *StateStore) Save(ctx context.Context, state *State) error {
442		_ = ctx // Reserved for future use
443	
444		// Validate session ID to prevent path traversal

290		// Append prompt to prompt.txt on filesystem so it's available for
291		// mid-turn commits (before SaveStep writes it to the shadow branch).
292		// Prompts are separated by "\n\n---\n\n" to support multiple turns.
293		if event.Prompt != "" {
294			sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
295			if sessionDirAbs, absErr := paths.AbsPath(ctx, sessionDir); absErr == nil {
296				if mkErr := os.MkdirAll(sessionDirAbs, 0o750); mkErr == nil {
297					promptPath := filepath.Join(sessionDirAbs, paths.PromptFileName)
298					existing, readErr := os.ReadFile(promptPath) //nolint:gosec // session metadata path
299					var content string
300					if readErr == nil && len(existing) > 0 {
301						content = string(existing) + "\n\n---\n\n" + event.Prompt
302					} else {
303						content = event.Prompt
304					}
305					if writeErr := os.WriteFile(promptPath, []byte(content), 0o600); writeErr != nil { //nolint:gosec // path from internal metadata, not user input
306						logging.Warn(logCtx, "failed to write prompt.txt",
307							slog.String("error", writeErr.Error()))
308					}
309				}
310			}
311		}
312	
313		// Ensure strategy setup and initialize session
314		_, initSpan := perf.Start(ctx, "init_session")
315		if err := strategy.EnsureSetup(ctx); err != nil {
316			logging.Warn(logCtx, "failed to ensure strategy setup",
317				slog.String("error", err.Error()))
318		}
319	
320		strat := GetStrategy(ctx)
321		if err := strat.InitializeSession(ctx, sessionID, ag.Type(), event.SessionRef, event.Prompt, event.Model); err != nil {
322			logging.Warn(logCtx, "failed to initialize session state",
323				slog.String("error", err.Error()))
324		}
325	
326		// Best-effort: adopt ENTIRE_REVIEW_* env vars set by `entire review` on
327		// the spawned agent process. Each agent process has its own env, so there
328		// is no file race across worktrees. Errors in load/save must not fail the turn.
329		if state, loadErr := strategy.LoadSessionState(ctx, sessionID); loadErr != nil {
330			logging.Warn(logCtx, "failed to load session state for review env adoption",
331				slog.String("error", loadErr.Error()))
332		} else if state != nil {
333			updated := *state
334			adoptReviewEnv(logCtx, &updated, string(ag.Name()))
335			if updated.Kind != state.Kind || updated.ReviewPrompt != state.ReviewPrompt || !slices.Equal(updated.ReviewSkills, state.ReviewSkills) {
336				if saveErr := strategy.SaveSessionState(ctx, &updated); saveErr != nil {
337					logging.Warn(logCtx, "failed to save session state after review env adoption",
338						slog.String("error", saveErr.Error()))
339				}
340			}
341		}
342		initSpan.End()
343	
344		return nil
345	}
